package main

import _ "embed"

// The glyph-only Cove icon in two tones, generated by website/scripts/gen-desktop-icons.mjs. Windows draws the
// taskbar and the tray in a light or dark theme chosen by the user, so the app picks the tone that reads on it.

//go:embed build/windows/icon-light.ico
var iconForLightTaskbar []byte

//go:embed build/windows/icon-dark.ico
var iconForDarkTaskbar []byte

// iconForTheme returns the icon for a light or dark taskbar: the deeper terracotta on a light bar, the lighter
// one on a dark bar.
func iconForTheme(lightTaskbar bool) []byte {
	if lightTaskbar {
		return iconForLightTaskbar
	}
	return iconForDarkTaskbar
}
